func testUsuarioToManyAddOpUsuAlertas(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Usuario
	var b, c, d, e Alertas

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, usuarioDBTypes, false, strmangle.SetComplement(usuarioPrimaryKeyColumns, usuarioColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Alertas{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, alertasDBTypes, false, strmangle.SetComplement(alertasPrimaryKeyColumns, alertasColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*Alertas{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddUsuAlertas(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.UsuID != first.UsuID {
			t.Error("foreign key was wrong value", a.UsuID, first.UsuID)
		}
		if a.UsuID != second.UsuID {
			t.Error("foreign key was wrong value", a.UsuID, second.UsuID)
		}

		if first.R.Usu != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Usu != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.UsuAlertas[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.UsuAlertas[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.UsuAlertas().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
