	if err != nil {
		t.Fatal(err)
	}

	count, err := a.UsuDocumentoVendas().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

