func testUsuarioToOneGrupoUsuarioUsingGpu(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local Usuario
	var foreign GrupoUsuario

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, usuarioDBTypes, false, usuarioColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Usuario struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, grupoUsuarioDBTypes, false, grupoUsuarioColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize GrupoUsuario struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	local.GpuID = foreign.GpuID
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Gpu().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if check.GpuID != foreign.GpuID {
		t.Errorf("want: %v, got %v", foreign.GpuID, check.GpuID)
	}

	ranAfterSelectHook := false
	AddGrupoUsuarioHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *GrupoUsuario) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := UsuarioSlice{&local}
	if err = local.L.LoadGpu(ctx, tx, false, (*[]*Usuario)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Gpu == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Gpu = nil
	if err = local.L.LoadGpu(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Gpu == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

